use vstd::prelude::*;

verus! {
    /// Logical specification: true exactly when `c` is '0'..='9'
    spec fn char_is_digit(c: char) -> bool {
        c >= '0' && c <= '9'
    }

    /// Implementation of the ASCII‐digit test, 
    /// proved to coincide with the spec above.
    fn is_ascii_digit(c: char) -> bool
        ensures
            result == char_is_digit(c)
    {
        // Rust char comparisons are fine here
        c >= '0' && c <= '9'
    }

    /// Returns true iff every character of `s` is in '0'..='9'.
    fn all_digits(s: String) -> bool
        ensures
            // we collect into a Vec<char> and view its length as an `int`
            let vec: Vec<char> = s.chars().collect();
            let n: int = vec.len() as int;
            result == (forall |j: int| 0 <= j < n ==> char_is_digit(vec[j as usize]))
    {
        // At run‐time, collect once so we can index
        let vec: Vec<char> = s.chars().collect();
        let n: int = vec.len() as int;

        let mut i: int = 0;
        let mut all: bool = true;

        // Process left‐to‐right, maintaining the invariant that
        // `all` holds exactly when every vec[0..i) is a digit.
        while i < n
            invariant 0 <= i && i <= n,
            invariant all == (forall |j: int| 0 <= j < i ==> char_is_digit(vec[j as usize])),
            decreases n - i,
        {
            all = all && is_ascii_digit(vec[i as usize]);
            i += 1;
        }

        all
    }
}

fn main() {
    // a few smoke tests at run‐time:
    assert!(is_ascii_digit('5'));
    assert!(!is_ascii_digit('a'));
    assert!(all_digits(String::from("0123456789")));
    assert!(!all_digits(String::from("12x34")));
    assert!(all_digits(String::new())); // the empty string is vacuously all digits
}